We now show that
\begin{equation}\label{eq:th_7_clean_4}
    B\cap A_1^c = B\cap A_2^c,
\end{equation}
so as to prove $\eqref{eq:th_7_clean_2} = \eqref{eq:th_7_clean_3}$. Under the event $B$, we have
\begin{equation}
\pi(\underline{e}(t^{*})\oplus \underline{e}(t^{*}+1))\in\mathcal{C}.
\end{equation}
For any $t'<t^{*}$,
\begin{equation}
\pi(\underline{e}(t')\oplus \underline{e}(t^{*}))
= \pi(\underline{e}(t')\oplus \underline{e}(t^{*}+1)) \oplus \pi(\underline{e}(t^{*}+1)\oplus \underline{e}(t^{*})).
\end{equation}
Since $\mathcal{C}$ is linear, the modulo-two sum of a codeword and a non-codeword is a non-codeword. Hence, under $B$, the condition
\begin{equation}
\pi(\underline{e}(t')\oplus \underline{e}(t^{*}+1))\notin\mathcal{C},\ \forall\, t'<t^{*}
\end{equation}
holds if and only if
\begin{equation}
\pi(\underline{e}(t')\oplus \underline{e}(t^{*}))\notin\mathcal{C},\ \forall\, t'<t^{*}.
\end{equation}
This proves \eqref{eq:th_7_clean_4}, and therefore
\begin{equation}
    \Pr(B\cap A_1^c)=\Pr(B\cap A_2^c).
\end{equation}
Substituting \eqref{eq:th_7_clean_2} and \eqref{eq:th_7_clean_3} into \eqref{eq:th_7_prove_2}, we obtain
\begin{align}
    P_{\mathrm{succ}}'-P_{\mathrm{succ}}
    &= p_{t^{*}+1}\Pr(B\cap A_2^c)-p_{t^{*}}\Pr(B\cap A_1^c) = \Pr(B\cap A_1^c)\left(p_{t^{*}+1}-p_{t^{*}}\right)\overset{(a)}{\geq}0,\label{eq:th_7_succ_diff_nonneg}
\end{align}
where $(a)$ follows from \eqref{eq:th_7_prove_0}. Hence, whenever an adjacent pair satisfies $p_{t^{*}}<p_{t^{*}+1}$, exchanging these two EPs cannot decrease $P_{\mathrm{succ}}$. The same reasoning applies to any index pair $(t,t+1)$ with $p_t<p_{t+1}$: the corresponding adjacent exchange does not decrease $P_{\mathrm{succ}}$.

Therefore, starting from any ordering of the fixed candidate EP set, we may repeatedly apply such adjacent exchanges (whenever some adjacent pair violates $p_t\ge p_{t+1}$) until the associated $\{p_t\}_{t=1}^{T}$ is non-increasing, and the decoding success probability never decreases along this process. In particular, let $\mathcal{E}$ maximize $P_{\mathrm{succ}}$ over all orderings of this candidate set, which exists because only finitely many such orderings exist. Performing the above exchanges from $\mathcal{E}$ preserves the value of $P_{\mathrm{succ}}$ at its global maximum, and after finitely many steps we obtain an ordering whose associated $\{p_t\}_{t=1}^{T}$ satisfies
\begin{equation}
p_1 \ge p_2 \ge \cdots \ge p_T.
\end{equation}
This exhibits an ordering of the fixed candidate EP set that maximizes the decoding success probability and whose associated sequence $\{p_t\}_{t=1}^{T}$ is non-increasing, as stated in the theorem.

\begin{align}
    P_{\mathrm{succ}}' - P_{\mathrm{succ}} ={}& \sum_{t=1}^{T}p'_t - \sum_{t=1}^{T}p'_t f(\mathcal{C},\mathcal{E}',t) - \sum_{t=1}^{T}p_t + \sum_{t=1}^{T}p_tf(\mathcal{C},\mathcal{E},t) \notag \\
    ={}& p_{t^{*}}f(\mathcal{C},\mathcal{E},t^{*}) + p_{t^{*}+1}f(\mathcal{C},\mathcal{E},t^{*}+1) - p'_{t^{*}}f(\mathcal{C},\mathcal{E}',t^{*}) - p'_{t^{*}+1}f(\mathcal{C},\mathcal{E}',t^{*}+1) \label{eq:th_7_prove_1}\\
    ={}& p_{t^{*}}f(\mathcal{C},\mathcal{E},t^{*}) + p_{t^{*}+1}f(\mathcal{C},\mathcal{E},t^{*}+1) - p_{t^{*}+1}f(\mathcal{C},\mathcal{E}',t^{*}) - p_{t^{*}}f(\mathcal{C},\mathcal{E}',t^{*}+1) \notag \\
    ={}& p_{t^{*}+1}(f(\mathcal{C},\mathcal{E},t^{*}+1) - f(\mathcal{C},\mathcal{E}',t^{*})) - p_{t^{*}}(f(\mathcal{C},\mathcal{E}',t^{*}+1) - f(\mathcal{C},\mathcal{E},t^{*})). \label{eq:th_7_prove_2}
\end{align}

\begin{align}
    f(\mathcal{C},\mathcal{E},t^{*}) &= \Pr(A_1),\ f(\mathcal{C},\mathcal{E},t^{*}+1) = \Pr(A_2 \cup B), \\
    f(\mathcal{C},\mathcal{E}',t^{*}) &= \Pr(A_2),\ f(\mathcal{C},\mathcal{E}',t^{*}+1) = \Pr(A_1 \cup B).
\end{align}

For an ordered codeword tuple $[\underline{u}(1),\ldots,\underline{u}(t)]$, define its weight relationship as the collection
\begin{equation}\label{eq:def_weight_relationship}
\mathcal{F}(\underline{u}(1),\ldots,\underline{u}(t))
\triangleq
\bigl(g(\underline{b})\bigr)_{\underline{b}\in\{0,1\}^t},
\end{equation}
where $g(\underline{0}) = N$, and for $\underline{b}=(b_1,\ldots,b_t)\neq \underline{0}$,
\begin{equation}
g(\underline{b})
= w_{\mathrm{H}}\!\left(
\bigoplus_{i=1}^{t} b_i\,\underline{u}(i)
\right),
\label{eq:def_g}
\end{equation}
where $w_{\mathrm{H}}(\underline{v})$ denotes the Hamming weight of $\underline{v}\in\{0,1\}^N$.

For any target weight-relationship vector $\mathbf{g}=\bigl(g(\underline{b})\bigr)_{\underline{b}\in\{0,1\}^t}$, define
\begin{equation}\label{eq:def_Z}
Z(\mathbf{g})
=
\sum_{[\underline{u}(1),\ldots,\underline{u}(t)]\in \mathcal{C}^t}
\mathbf{1}\!\left(
\mathcal{F}(\underline{u}(1),\ldots,\underline{u}(t))=\mathbf{g}
\right),
\end{equation}
which counts the number of ordered codeword tuples in $\mathcal{C}^t$ having the weight relationship $\mathbf{g}$.

\label{th:linear_pre_target_hit}
For any linear block code $\mathcal{C}$, the pre-target codeword-hit probability admits the representation
\begin{equation}\label{eq:th_line_mif_main}
f(\mathcal{C},\mathcal{E},t)
= \sum_{j=1}^{t-1} (-1)^{j-1}
\sum_{1\le i_1<\cdots<i_j<t}
\frac{1}{N!}\,
Z(\mathbf{g})\,
\mathcal{H}(\mathbf{g}),
\end{equation}
where $\mathbf{g}=\mathcal{F}(\underline{e}(i_1,t),\ldots,\underline{e}(i_j,t))$, and $\mathcal{H}(\mathbf{g})$ is the coordinate-permutation factor characterized in Proposition~\ref{prop:rearrange_number}.

\label{lem:linear_pre_target_hit}
For any $1\le i_1<i_2<\cdots<i_j<t$, the joint probability 
$\Pr\!\left(\bigcap_{k=1}^{j}A_{i_k t}\right)$ can be expressed as
\begin{equation}
\sum_{\substack{
[\underline{u}(1),\ldots,\underline{u}(j)] \in \mathcal{C}^{j}:\\
\mathcal{F}(\underline{u}(1),\ldots,\underline{u}(j)) = \mathbf{g}
}}
\Pr\!\left(
\bigcap_{k=1}^{j}\{\pi(\underline{e}(i_k,t))=\underline{u}(k)\}
\right),
\label{eq:linear_pre_target_hit_prop}
\end{equation}
where $\mathbf{g} = \mathcal{F}\big(\underline{e}(i_1,t),\ldots,\underline{e}(i_j,t)\big)$.

By definition, $\Pr\!\left(\bigcap_{k=1}^{j}A_{i_k t}\right)=\Pr\!\left(\bigcap_{k=1}^{j}\{\pi(\underline{e}(i_k,t))\in\mathcal{C}\}\right).$ Partition the event on the right-hand side according to the ordered codeword tuple $[\underline{u}(1),\ldots,\underline{u}(j)]\in\mathcal{C}^j$ satisfying $\pi(\underline{e}(i_k,t))=\underline{u}(k)$ for all $k$. Then
\begin{equation}
\Pr\!\left(\bigcap_{k=1}^{j}A_{i_k t}\right)
=
\sum_{[\underline{u}(1),\ldots,\underline{u}(j)]\in\mathcal{C}^j}
\Pr\!\left(\bigcap_{k=1}^{j}\{\pi(\underline{e}(i_k,t))=\underline{u}(k)\}\right).
\label{eq:linear_pre_target_hit_p2_raw}
\end{equation}
Now consider any term in \eqref{eq:linear_pre_target_hit_p2_raw} with nonzero probability. Then there exists a coordinate permutation $\sigma$ such that $\sigma(\underline{e}(i_k,t))=\underline{u}(k)$ for all $k$. Since coordinate permutations preserve the Hamming weights of all XOR combinations, we must have
\begin{equation}
\mathcal{F}(\underline{u}(1),\ldots,\underline{u}(j))
=
\mathcal{F}(\underline{e}(i_1,t),\ldots,\underline{e}(i_j,t))
=
\mathbf{g}.
\end{equation}
Therefore, every term with $\mathcal{F}(\underline{u}(1),\ldots,\underline{u}(j))\neq \mathbf{g}$ is zero, and \eqref{eq:linear_pre_target_hit_prop} follows.

\label{prop:rearrange_number}
For any two ordered binary vector tuples 
$[\underline{x}(1),\ldots,\underline{x}(j)]$ and 
$[\underline{u}(1),\ldots,\underline{u}(j)]$, suppose that
\begin{equation}
\mathcal{F}(\underline{x}(1),\ldots,\underline{x}(j))
=
\mathcal{F}(\underline{u}(1),\ldots,\underline{u}(j))
=
\mathbf{g}.
\end{equation}
For each coordinate $k$, define the state of $[\underline{x}(1),\ldots,\underline{x}(j)]$ by
\begin{equation}
\underline{S}_x(k)=[x_k(1),\ldots,x_k(j)]\in\{0,1\}^j,
\end{equation}
and define $\underline{S}_u(k)$ similarly. Let
\begin{equation}
J(\underline{s})=\bigl|\{k:\underline{S}_x(k)=\underline{s}\}\bigr|,
\qquad \underline{s}\in\{0,1\}^j.
\end{equation}
Then the number of coordinate permutations $\sigma$ satisfying
$\sigma(\underline{x}(i))=\underline{u}(i)$ for all $i=1,\ldots,j$ is
\begin{equation}\label{eq:H_by_J}
\mathcal{H}(\mathbf{g})
=
\prod_{\underline{s}\in\{0,1\}^j} J(\underline{s})!.
\end{equation}

For a state $\underline{s}\in\{0,1\}^j$, define
\begin{equation}
\mathcal{I}_x(\underline{s})=\{k:\underline{S}_x(k)=\underline{s}\},
\qquad
\mathcal{I}_u(\underline{s})=\{k:\underline{S}_u(k)=\underline{s}\}.
\end{equation}
A permutation $\sigma$ satisfies $\sigma(\underline{x}(i))=\underline{u}(i)$ for all $i$ if and only if, for every state $\underline{s}$, it maps the coordinates in $\mathcal{I}_x(\underline{s})$ bijectively onto the coordinates in $\mathcal{I}_u(\underline{s})$.

This correspondence can be visualized by arranging the vectors into a matrix form, where each column represents a coordinate and its associated state:
\begin{align}
    &\left[\begin{array}[pos]{cccc}
        x_1(1) & x_2(1) & \cdots & x_N(1)\\
        x_1(2) & x_2(2) & \cdots & x_N(2)\\
        \vdots & \vdots & \ddots & \vdots\\
        x_1(j) & x_2(j) & \cdots & x_N(j)
    \end{array}\right]
    \overset{\sigma}{\longrightarrow}
    \left[\begin{array}[pos]{cccc}
        \sigma(\underline{x}(1))_1 & \sigma(\underline{x}(1))_2 & \cdots & \sigma(\underline{x}(1))_N\\
        \sigma(\underline{x}(2))_1 & \sigma(\underline{x}(2))_2 & \cdots & \sigma(\underline{x}(2))_N\\
        \vdots & \vdots & \ddots & \vdots\\
        \sigma(\underline{x}(j))_1 & \sigma(\underline{x}(j))_2 & \cdots & \sigma(\underline{x}(j))_N
    \end{array}\right],
    \label{eq:matrix}
\end{align}
where each column is a state vector and must be mapped to a column with the same state in the target tuple.

Because the two tuples have the same weight relationship $\mathbf{g}$, their state multiplicities agree for all $\underline{s}$, as made explicit in Proposition~\ref{prop:Bj_recursion}. Hence, for each state $\underline{s}$ there are $J(\underline{s})!$ possible bijections between $\mathcal{I}_x(\underline{s})$ and $\mathcal{I}_u(\underline{s})$. Multiplying over all states gives \eqref{eq:H_by_J}.

\begin{align}
    &\left[\begin{array}[pos]{cccc}
        x_1(1) & x_2(1) & \cdots & x_N(1)\\
        x_1(2) & x_2(2) & \cdots & x_N(2)\\
        \vdots & \vdots & \ddots & \vdots\\
        x_1(j) & x_2(j) & \cdots & x_N(j)
    \end{array}\right]
    \overset{\sigma}{\longrightarrow}
    \left[\begin{array}[pos]{cccc}
        \sigma(\underline{x}(1))_1 & \sigma(\underline{x}(1))_2 & \cdots & \sigma(\underline{x}(1))_N\\
        \sigma(\underline{x}(2))_1 & \sigma(\underline{x}(2))_2 & \cdots & \sigma(\underline{x}(2))_N\\
        \vdots & \vdots & \ddots & \vdots\\
        \sigma(\underline{x}(j))_1 & \sigma(\underline{x}(j))_2 & \cdots & \sigma(\underline{x}(j))_N
    \end{array}\right],
    \label{eq:matrix}
\end{align}

\label{prop:Bj_recursion}
Let $\mathbf{g}^{(j)}=\bigl(g(\underline{b})\bigr)_{\underline{b}\in\{0,1\}^j}$ and $\mathbf{J}^{(j)}=\bigl(J(\underline{s})\bigr)_{\underline{s}\in\{0,1\}^j}$, where both vectors are ordered according to the lexicographic order on $\{0,1\}^j$. Then
\begin{equation}\label{eq:relation_g_and_j_matrix}
\mathbf{g}^{(j)}=\mathbf{B}_j\,\mathbf{J}^{(j)},
\end{equation}
where the matrix-vector product is taken over the integers, and $\mathbf{B}_j$ is the $2^j\times 2^j$ matrix indexed by $\{0,1\}^j\times\{0,1\}^j$ with entries
\begin{equation}\label{eq:Bj_entry_new}
\bigl[\mathbf{B}_j\bigr]_{\underline{b},\underline{s}}
=
\begin{cases}
1, & \underline{b}=\underline{0},\\
\underline{b}\cdot \underline{s}, & \underline{b}\neq \underline{0},
\end{cases}
\qquad
\underline{b},\underline{s}\in\{0,1\}^j,
\end{equation}
and $\underline{b}\cdot \underline{s}=\bigoplus_{i=1}^j b_i s_i$.
Moreover, $\mathbf{B}_j$ admits the recursion
\begin{equation}\label{eq:Bj_recursion_new}
\mathbf{B}_{j+1}
=
\begin{bmatrix}
\mathbf{B}_j & \mathbf{B}_j\\
\mathbf{E}^{2^j\times 2^j}_{1,1:2^j}\oplus \mathbf{B}_j &
\mathbf{E}^{2^j\times 2^j}_{1,1:2^j}\oplus \mathbf{1}^{2^j\times 2^j}\oplus \mathbf{B}_j
\end{bmatrix},
\qquad
\mathbf{B}_1=
\begin{bmatrix}
1 & 1\\
0 & 1
\end{bmatrix}.
\end{equation}
Furthermore, $\mathbf{B}_j$ is invertible over $\mathbb{R}$, and hence $\mathbf{J}^{(j)}$ can be uniquely recovered from $\mathbf{g}^{(j)}$ via $\mathbf{J}^{(j)}=\mathbf{B}_j^{-1}\mathbf{g}^{(j)}$.

\label{coro:single_event_prob}
For any linear block code $\mathcal{C}$, let
\begin{equation}
\mathbf{g}_{it}^{(1)}
\triangleq
\bigl(N,w_{\mathrm{H}}(\underline{e}(i,t))\bigr).
\end{equation}
Then the probability of the event $A_{it}=\{\pi(\underline{e}(i,t))\in\mathcal{C}\}$ is given by
\begin{equation}\label{eq:single_event_prob}
\Pr(A_{it}) = \frac{Z(\mathbf{g}_{it}^{(1)})}{C_{N}^{w_{\mathrm{H}}(\underline{e}(i,t))}}.
\end{equation}
Consequently, the first-order BLER upper bound in \eqref{eq:first_order_bler_bound} can be written as
\begin{equation}\label{eq:first_order_bler_bound_weight}
P_{\mathrm{err}}
\le
1-\sum_{t=1}^{T}p_t + 
\sum_{t=1}^{T}p_t\sum_{i=1}^{t-1}
\frac{Z(\mathbf{g}_{it}^{(1)})}{C_{N}^{w_{\mathrm{H}}(\underline{e}(i,t))}}.
\end{equation}

Applying Theorem~\ref{th:linear_pre_target_hit} with $j=1$, we have
\begin{align}
\Pr(A_{it}) = \frac{1}{N!}Z(\mathbf{g}_{it}^{(1)})\mathcal{H}(\mathbf{g}_{it}^{(1)}).
\end{align}
To compute $\mathcal{H}(\mathbf{g}_{it}^{(1)})$, note that for $j=1$,
\begin{equation}
\left[\begin{array}{c}
J(0) \\ J(1)
\end{array}\right]
=
\left[\begin{array}{cc}
1 & 1 \\
0 & 1
\end{array}\right]^{-1}
\left[\begin{array}{c}
N \\ w_{\mathrm{H}}(\underline{e}(i,t))
\end{array}\right]
=
\left[\begin{array}{c}
N-w_{\mathrm{H}}(\underline{e}(i,t)) \\ w_{\mathrm{H}}(\underline{e}(i,t))
\end{array}\right].
\end{equation}
Hence $\mathcal{H}(\mathbf{g}_{it}^{(1)})=\bigl(N-w_{\mathrm{H}}(\underline{e}(i,t))\bigr)!w_{\mathrm{H}}(\underline{e}(i,t))!$, which gives
\begin{equation}
\Pr(A_{it}) = \frac{Z(\mathbf{g}_{it}^{(1)})}{C_{N}^{w_{\mathrm{H}}(\underline{e}(i,t))}}.
\end{equation}
Substituting this expression into \eqref{eq:first_order_bler_bound} gives \eqref{eq:first_order_bler_bound_weight}.

\begin{equation}
\left[\begin{array}{c}
J(0) \\ J(1)
\end{array}\right]
=
\left[\begin{array}{cc}
1 & 1 \\
0 & 1
\end{array}\right]^{-1}
\left[\begin{array}{c}
N \\ w_{\mathrm{H}}(\underline{e}(i,t))
\end{array}\right]
=
\left[\begin{array}{c}
N-w_{\mathrm{H}}(\underline{e}(i,t)) \\ w_{\mathrm{H}}(\underline{e}(i,t))
\end{array}\right].
\end{equation}

\label{ex:hamming_first_order}
Consider the Hamming$(7,4)$ code. For the first-order relationship associated with an EP difference,
$\mathbf{g}^{(1)}=(7,w_{\mathrm{H}}(\underline{e}(i,t)))$. The nonzero multiplicities are
\begin{equation}
Z((7,0))=1,\qquad Z((7,3))=7,\qquad Z((7,4))=7,\qquad Z((7,7))=1,
\end{equation}
with zero multiplicity for all other Hamming weights. For this first-order relationship,
\begin{equation}
\mathcal{H}(\mathbf{g}^{(1)})=
\bigl(7-w_{\mathrm{H}}(\underline{e}(i,t))\bigr)!w_{\mathrm{H}}(\underline{e}(i,t))!,
\qquad
\begin{array}{c|cccc}
w_{\mathrm{H}}(\underline{e}(i,t)) & 0 & 3 & 4 & 7\\ \hline
Z(\mathbf{g}^{(1)}) & 1 & 7 & 7 & 1\\
\mathcal{H}(\mathbf{g}^{(1)}) & 7! & 4!3! & 3!4! & 7!\\
\Pr(A_{it}) & 1 & 1/5 & 1/5 & 1
\end{array}
\end{equation}
For all other Hamming weights, $\Pr(A_{it})=0$. For example, the EPs $1100000$ and $0010000$ differ by $1110000$, whose weight is $3$. If one of them is the target EP, testing the other one first produces a competing codeword with probability $Z((7,3))/C_7^3=7/C_7^3=1/5$. The zero-weight case is listed only for completeness; it does not arise for distinct EPs.

